package fraymus.execution;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

/**
 * ExecutionBridge - Bare-metal code execution bridge for Fraymus AGI
 * 
 * This class provides the capability to execute code generated by LLM brains
 * on the local CPU, capturing real terminal output instead of hallucinations.
 * 
 * This is the critical "Executor Node" that transforms Fraymus from a "Thinker"
 * to a "Doer" - the final step to AGI sovereignty.
 */
public class ExecutionBridge {
    
    private static final String TEMP_DIR = System.getProperty("java.io.tmpdir");
    private static final int EXECUTION_TIMEOUT_MS = 30000; // 30 seconds
    
    /**
     * CodeBlock represents a detected code block with language and content
     */
    public static class CodeBlock {
        private final String language;
        private final String code;
        private final int startLine;
        private final int endLine;
        
        public CodeBlock(String language, String code, int startLine, int endLine) {
            this.language = language;
            this.code = code;
            this.startLine = startLine;
            this.endLine = endLine;
        }
        
        public String getLanguage() { return language; }
        public String getCode() { return code; }
        public int getStartLine() { return startLine; }
        public int getEndLine() { return endLine; }
    }
    
    /**
     * ExecutionResult represents the result of code execution
     */
    public static class ExecutionResult {
        private final String stdout;
        private final String stderr;
        private final int exitCode;
        private final long executionTimeMs;
        private final boolean success;
        
        public ExecutionResult(String stdout, String stderr, int exitCode, long executionTimeMs) {
            this.stdout = stdout;
            this.stderr = stderr;
            this.exitCode = exitCode;
            this.executionTimeMs = executionTimeMs;
            this.success = (exitCode == 0);
        }
        
        public String getStdout() { return stdout; }
        public String getStderr() { return stderr; }
        public int getExitCode() { return exitCode; }
        public long getExecutionTimeMs() { return executionTimeMs; }
        public boolean isSuccess() { return success; }
        
        @Override
        public String toString() {
            if (success) {
                return stdout.trim();
            } else {
                return "ERROR (exit code " + exitCode + "): " + stderr.trim();
            }
        }
    }
    
    /**
     * Detect code blocks in text using multiple formats
     * 
     * Supports:
     * - Markdown code fences: ```language code ```
     * - HTML code tags: <code>code</code>
     * - Inline code: `code`
     * - Plain code blocks (indented)
     * 
     * @param text The text to scan for code blocks
     * @return List of detected CodeBlock objects
     */
    public List<CodeBlock> detectCodeBlocks(String text) {
        List<CodeBlock> blocks = new ArrayList<>();
        
        // Pattern 1: Markdown code blocks: ```language code ```
        Pattern markdownPattern = Pattern.compile("```(\\w*)\\n([\\s\\S]*?)```");
        Matcher markdownMatcher = markdownPattern.matcher(text);
        
        while (markdownMatcher.find()) {
            String language = markdownMatcher.group(1).toLowerCase();
            String code = markdownMatcher.group(2);
            int startLine = countLines(text.substring(0, markdownMatcher.start()));
            int endLine = startLine + countLines(code);
            
            blocks.add(new CodeBlock(language, code, startLine, endLine));
        }
        
        // Pattern 2: HTML code tags: <code>code</code>
        Pattern htmlPattern = Pattern.compile("<code>([\\s\\S]*?)</code>", Pattern.CASE_INSENSITIVE);
        Matcher htmlMatcher = htmlPattern.matcher(text);
        
        while (htmlMatcher.find()) {
            String code = htmlMatcher.group(1);
            int startLine = countLines(text.substring(0, htmlMatcher.start()));
            int endLine = startLine + countLines(code);
            
            // Detect language from content
            String language = detectLanguage(code);
            blocks.add(new CodeBlock(language, code, startLine, endLine));
        }
        
        // Pattern 3: Inline code with language hint: `code` (language: ...)
        Pattern inlinePattern = Pattern.compile("`([^`]+)`\\s*\\(language:\\s*(\\w+)\\)");
        Matcher inlineMatcher = inlinePattern.matcher(text);
        
        while (inlineMatcher.find()) {
            String code = inlineMatcher.group(1);
            String language = inlineMatcher.group(2).toLowerCase();
            int startLine = countLines(text.substring(0, inlineMatcher.start()));
            int endLine = startLine + countLines(code);
            
            blocks.add(new CodeBlock(language, code, startLine, endLine));
        }
        
        return blocks;
    }
    
    /**
     * Detect programming language from code content
     */
    private String detectLanguage(String code) {
        String lowerCode = code.toLowerCase();
        
        if (lowerCode.contains("public class") || lowerCode.contains("import java") || lowerCode.contains("void main")) {
            return "java";
        } else if (lowerCode.contains("def ") || lowerCode.contains("import ") || lowerCode.contains("print(")) {
            return "python";
        } else if (lowerCode.contains("function ") || lowerCode.contains("const ") || lowerCode.contains("let ")) {
            return "javascript";
        } else if (lowerCode.contains("#include") || lowerCode.contains("int main")) {
            return "cpp";
        } else if (lowerCode.contains("<!doctype html") || lowerCode.contains("<html") || lowerCode.contains("<div")) {
            return "html";
        } else if (lowerCode.contains("body {") || lowerCode.contains("background-color")) {
            return "css";
        }
        
        return "text";
    }
    
    /**
     * Execute a single code block
     * 
     * @param block The CodeBlock to execute
     * @return ExecutionResult with stdout, stderr, exit code
     */
    public ExecutionResult executeCodeBlock(CodeBlock block) {
        String language = block.getLanguage().toLowerCase();
        
        switch (language) {
            case "java":
                return executeJava(block.getCode());
            case "python":
            case "py":
                return executePython(block.getCode());
            case "html":
                return executeHTML(block.getCode());
            case "css":
                return executeCSS(block.getCode());
            case "javascript":
            case "js":
                return executeJavaScript(block.getCode());
            default:
                // Try to execute as shell command
                return executeShell(block.getCode());
        }
    }
    
    /**
     * Execute Java code
     * 
     * @param code The Java source code
     * @return ExecutionResult with stdout, stderr, exit code
     */
    public ExecutionResult executeJava(String code) {
        try {
            // Extract class name from code
            String className = extractClassName(code);
            
            // Create temporary directory for compilation
            Path tempDir = Files.createTempDirectory("fraymus_java_exec_");
            Path javaFile = tempDir.resolve(className + ".java");
            
            // Write code to file
            Files.writeString(javaFile, code);
            
            // Compile
            long startTime = System.currentTimeMillis();
            Process compileProcess = new ProcessBuilder("javac", javaFile.toString())
                .directory(tempDir.toFile())
                .redirectErrorStream(true)
                .start();
            
            String compileOutput = readProcessOutput(compileProcess);
            int compileExitCode = compileProcess.waitFor();
            
            if (compileExitCode != 0) {
                cleanup(tempDir);
                return new ExecutionResult("", "Compilation failed: " + compileOutput,
                    compileExitCode, System.currentTimeMillis() - startTime);
            }
            
            // Execute
            Path classFile = tempDir.resolve(className + ".class");
            
            if (!Files.exists(classFile)) {
                cleanup(tempDir);
                return new ExecutionResult("", "Class file not found after compilation",
                    -1, System.currentTimeMillis() - startTime);
            }
            
            Process execProcess = new ProcessBuilder("java", "-cp", tempDir.toString(), className)
                .directory(tempDir.toFile())
                .redirectErrorStream(true)
                .start();
            
            String execOutput = readProcessOutput(execProcess);
            int execExitCode = execProcess.waitFor();
            long executionTime = System.currentTimeMillis() - startTime;
            
            // Cleanup
            cleanup(tempDir);
            
            return new ExecutionResult(execOutput, "", execExitCode, executionTime);
            
        } catch (Exception e) {
            return new ExecutionResult("", "Execution error: " + e.getMessage(), -1, 0);
        }
    }
    
    /**
     * Execute Python code
     * 
     * @param code The Python source code
     * @return ExecutionResult with stdout, stderr, exit code
     */
    public ExecutionResult executePython(String code) {
        try {
            long startTime = System.currentTimeMillis();
            
            // Execute Python code directly
            Process process = new ProcessBuilder("python", "-c", code)
                .redirectErrorStream(true)
                .start();
            
            String output = readProcessOutput(process);
            int exitCode = process.waitFor();
            long executionTime = System.currentTimeMillis() - startTime;
            
            return new ExecutionResult(output, "", exitCode, executionTime);
            
        } catch (Exception e) {
            return new ExecutionResult("", "Python execution error: " + e.getMessage(), -1, 0);
        }
    }
    
    /**
     * Execute HTML code (save to file and optionally open in browser)
     * 
     * @param code The HTML source code
     * @return ExecutionResult with file path and status
     */
    public ExecutionResult executeHTML(String code) {
        try {
            long startTime = System.currentTimeMillis();
            
            // Create output directory
            Path outputDir = Paths.get("fraymus_output");
            if (!Files.exists(outputDir)) {
                Files.createDirectories(outputDir);
            }
            
            // Save HTML file
            Path htmlFile = outputDir.resolve("index.html");
            Files.writeString(htmlFile, code);
            
            String message = "HTML file saved to: " + htmlFile.toAbsolutePath();
            long executionTime = System.currentTimeMillis() - startTime;
            
            return new ExecutionResult(message, "", 0, executionTime);
            
        } catch (Exception e) {
            return new ExecutionResult("", "HTML execution error: " + e.getMessage(), -1, 0);
        }
    }
    
    /**
     * Execute CSS code (save to file)
     * 
     * @param code The CSS source code
     * @return ExecutionResult with file path and status
     */
    public ExecutionResult executeCSS(String code) {
        try {
            long startTime = System.currentTimeMillis();
            
            // Create output directory
            Path outputDir = Paths.get("fraymus_output");
            if (!Files.exists(outputDir)) {
                Files.createDirectories(outputDir);
            }
            
            // Save CSS file
            Path cssFile = outputDir.resolve("styles.css");
            Files.writeString(cssFile, code);
            
            String message = "CSS file saved to: " + cssFile.toAbsolutePath();
            long executionTime = System.currentTimeMillis() - startTime;
            
            return new ExecutionResult(message, "", 0, executionTime);
            
        } catch (Exception e) {
            return new ExecutionResult("", "CSS execution error: " + e.getMessage(), -1, 0);
        }
    }
    
    /**
     * Execute JavaScript code (save to file)
     * 
     * @param code The JavaScript source code
     * @return ExecutionResult with file path and status
     */
    public ExecutionResult executeJavaScript(String code) {
        try {
            long startTime = System.currentTimeMillis();
            
            // Create output directory
            Path outputDir = Paths.get("fraymus_output");
            if (!Files.exists(outputDir)) {
                Files.createDirectories(outputDir);
            }
            
            // Save JavaScript file
            Path jsFile = outputDir.resolve("script.js");
            Files.writeString(jsFile, code);
            
            String message = "JavaScript file saved to: " + jsFile.toAbsolutePath();
            long executionTime = System.currentTimeMillis() - startTime;
            
            return new ExecutionResult(message, "", 0, executionTime);
            
        } catch (Exception e) {
            return new ExecutionResult("", "JavaScript execution error: " + e.getMessage(), -1, 0);
        }
    }
    
    /**
     * Execute shell command
     * 
     * @param command The shell command to execute
     * @return ExecutionResult with stdout, stderr, exit code
     */
    public ExecutionResult executeShell(String command) {
        try {
            long startTime = System.currentTimeMillis();
            
            // Execute shell command
            Process process;
            if (System.getProperty("os.name").toLowerCase().contains("win")) {
                process = new ProcessBuilder("cmd", "/c", command)
                    .redirectErrorStream(true)
                    .start();
            } else {
                process = new ProcessBuilder("sh", "-c", command)
                    .redirectErrorStream(true)
                    .start();
            }
            
            String output = readProcessOutput(process);
            int exitCode = process.waitFor();
            long executionTime = System.currentTimeMillis() - startTime;
            
            return new ExecutionResult(output, "", exitCode, executionTime);
            
        } catch (Exception e) {
            return new ExecutionResult("", "Shell execution error: " + e.getMessage(), -1, 0);
        }
    }
    
    /**
     * Process text to execute any code blocks and replace with real output
     * 
     * @param text The text containing code blocks
     * @return Text with code blocks replaced by execution results
     */
    public String processText(String text) {
        List<CodeBlock> blocks = detectCodeBlocks(text);
        if (blocks.isEmpty()) {
            return text;
        }
        
        String result = text;
        // Process blocks in reverse order to maintain line numbers
        for (int i = blocks.size() - 1; i >= 0; i--) {
            CodeBlock block = blocks.get(i);
            ExecutionResult execResult = executeCodeBlock(block);
            
            // Replace code block with execution result
            String replacement = "```\n" + execResult.toString() + "\n```";
            Pattern pattern = Pattern.compile("```" + Pattern.quote(block.getLanguage()) + "\\n[\\s\\S]*?```");
            Matcher matcher = pattern.matcher(result);
            
            if (matcher.find()) {
                result = matcher.replaceFirst(replacement);
            }
        }
        
        return result;
    }
    
    // Helper methods
    
    private String readProcessOutput(Process process) throws IOException {
        StringBuilder output = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }
        }
        return output.toString();
    }
    
    private int countLines(String text) {
        if (text == null || text.isEmpty()) return 0;
        return text.split("\n").length;
    }
    
    private String extractClassName(String javaCode) {
        Pattern pattern = Pattern.compile("public\\s+class\\s+(\\w+)");
        Matcher matcher = pattern.matcher(javaCode);
        if (matcher.find()) {
            return matcher.group(1);
        }
        return "TempExecution";
    }
    
    private void cleanup(Path tempDir) throws IOException {
        if (Files.exists(tempDir)) {
            Files.walk(tempDir)
                .sorted(Comparator.reverseOrder())
                .forEach(path -> {
                    try {
                        Files.delete(path);
                    } catch (IOException e) {
                        // Ignore cleanup errors
                    }
                });
        }
    }
}
